/*
 * A041540  Numerators of continued fraction convergents to sqrt(287).
 * https://oeis.org/A041540
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, cofr, frac, easy
 * Formula:   a(n) = numerator of the n-th convergent of sqrt(287) using the
 *            recurrence h_n = a_n*h_{n-1} + h_{n-2}, with partial quotients
 *            generated by the classic continued‑fraction algorithm for
 *            sqrt(287)
 * Range:     u8 n <= 1, u16 n <= 5, u32 n <= 13, u64 n <= 27, u128 n <= 55,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>

static const uint64_t D   = 287;   /* the radicand */
static const int       a0  = 16;   /* floor(sqrt(287)) */

seq_t a(idx_t n)
{
    if (n == 0) return (seq_t)a0;

    /* initial numerator values: h_{-1}=1, h_0=a0 */
    seq_t h_prev2 = (seq_t)1;         /* h_{i-2}  */
    seq_t h_prev1 = (seq_t)a0;        /* h_{i-1}  */

    /* state for generating the partial quotients a_i of sqrt(D) */
    uint64_t m_cur = 0;               /* m_{i}   */
    uint64_t d_cur = 1;               /* d_{i}   */
    int       a_cur = a0;             /* a_{i}   */

    for (idx_t i = 1; i <= n; ++i) {
        /* generate next partial quotient a_{i} */
        uint64_t m_next = d_cur * (uint64_t)a_cur - m_cur;
        uint64_t d_next = (D - m_next * m_next) / d_cur;
        int a_next = (a0 + m_next) / d_next;

        /* update the continued‑fraction state */
        m_cur = m_next;
        d_cur = d_next;
        a_cur = a_next;

        /* compute the next numerator h_i = a_i*h_{i-1} + h_{i-2} */
        seq_t h_curr = (seq_t)a_next * h_prev1 + h_prev2;

        /* shift for the next iteration */
        h_prev2 = h_prev1;
        h_prev1 = h_curr;
    }

    return h_prev1;
}
